50:   ): CurateGraphResult {
51:     const convergence = convergeStructuralGraph(structuralGraph, options);
52:     const existingDocument = this.readExistingDocument();
53:     const document = mergeCuratedGroup(existingDocument, convergence.group, {
54:       generatedAt: options.generatedAt,
55:     });
56: 
57:     // Reuse the Extension's runtime parser before any filesystem mutation.
58:     parseAgentGraphDocument(document);
59:     this.writeAtomically(document);
60:     return {
61:       document,
62:       group: document.groups.find(
63:         (group) => group.key === convergence.group.key
64:       )!,
65:       statistics: convergence.statistics,
66:       warnings: convergence.warnings,
67:     };
