27:       'skills',
28:       this.skillName
29:     );
30:   }
31: 
32:   public getInstalledSkillPath(workspaceRoot: string): string {
33:     return path.join(this.getInstallDirectory(workspaceRoot), 'SKILL.md');
34:   }
35: 
36:   public isInstalled(workspaceRoot: string): boolean {
37:     return fs.existsSync(this.getInstallDirectory(workspaceRoot));
38:   }
