40:   public install(workspaceRoot: string, overwrite = false): string {
41:     const sourceSkill = path.join(this.sourceDirectory, 'SKILL.md');
42:     if (!fs.existsSync(sourceSkill)) {
43:       throw new Error(`Bundled skill is missing: ${sourceSkill}`);
44:     }
45:     if (this.skillName === QUERY_SKILL_NAME && !fs.existsSync(path.join(this.sourceDirectory, 'scripts', 'query.cjs'))) {
