50:     if (this.isInstalled(workspaceRoot) && !overwrite) {
51:       throw new Error(`Skill is already installed: ${targetDirectory}`);
52:     }
53: 
54:     this.copyDirectory(this.sourceDirectory, targetDirectory, overwrite);
55:     return this.getInstalledSkillPath(workspaceRoot);
56:   }
57: 
58:   private copyDirectory(
59:     sourceDirectory: string,
60:     targetDirectory: string,
61:     overwrite: boolean
62:   ): void {
63:     fs.mkdirSync(targetDirectory, { recursive: true });
